package com.rulecraft.decisionops.deployment.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="runtime_deployment_event")
public class RuntimeDeploymentEvent {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="deployment_id",nullable=false)private UUID deploymentId;@Column(name="event_type",nullable=false,length=32)private String eventType;@Enumerated(EnumType.STRING)@Column(name="from_state",length=24)private RuntimeDeploymentState fromState;@Enumerated(EnumType.STRING)@Column(name="to_state",nullable=false,length=24)private RuntimeDeploymentState toState;@Column(name="actor_id",nullable=false)private UUID actorId;@Column(name="actor_name",nullable=false,length=160)private String actorName;@Column(length=600)private String note;@Column(name="created_at",nullable=false)private Instant createdAt;protected RuntimeDeploymentEvent(){}public RuntimeDeploymentEvent(UUID tenantId,UUID deploymentId,String eventType,RuntimeDeploymentState from,RuntimeDeploymentState to,UUID actor,String actorName,String note,Instant now){id=UUID.randomUUID();this.tenantId=tenantId;this.deploymentId=deploymentId;this.eventType=eventType;fromState=from;toState=to;actorId=actor;this.actorName=actorName;this.note=note;createdAt=now;}public UUID getId(){return id;}public String getEventType(){return eventType;}public RuntimeDeploymentState getFromState(){return fromState;}public RuntimeDeploymentState getToState(){return toState;}public String getActorName(){return actorName;}public String getNote(){return note;}public Instant getCreatedAt(){return createdAt;}}
